package cn.adc.duration;
import cn.adc.PgITSupport;import cn.adc.shared.audit.*;import cn.adc.shared.db.*;import tools.jackson.databind.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import java.util.*;import java.time.*;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="ADC_P0_IT_ENABLED",matches="true")
class DurationPublicationIT {
 @Test void successfulDraftEditRejectsStaleTokenAndOriginalCreationRecoveryFollowsActualHistory()throws Exception {var s=service();var input=AuditDocuments.JSON.createObjectNode().put("projectName","SYNTHETIC edit flow").put("durationMinutes",30);var created=s.create(UUID.randomUUID(),input);var row=created.result().path("targetVersion");long id=row.path("project_id").longValue();var edit=AuditDocuments.JSON.createObjectNode().put("projectName","SYNTHETIC edited").put("durationMinutes",40).put("expectedStateToken",AuditDocuments.hash(row)).put("reason","SYNTHETIC corrected");var key=UUID.randomUUID();assertEquals("SUCCEEDED",s.edit(key,id,1,edit).businessOutcome());assertEquals(40,s.version(id,1).path("duration_minutes").intValue());assertEquals("SUCCEEDED",s.edit(key,id,1,edit).businessOutcome());assertEquals("REJECTED",s.edit(UUID.randomUUID(),id,1,edit).businessOutcome());assertEquals("SUCCEEDED",s.recover(created.requestReference()).businessOutcome());}
 List<String> originalRows()throws Exception {var out=new java.util.ArrayList<String>();try(var c=PgITSupport.app().getConnection();var st=c.createStatement()){for(String table:List.of("clinic","dentist","patient","reception_schedule_version","appointment","appointment_resolution","visit","appointment_change_history","schedule_maintenance_issue","operation_audit_event"))try(var r=st.executeQuery("SELECT md5(COALESCE(string_agg(row_to_json(t)::text, E'\\n' ORDER BY row_to_json(t)::text),'')) FROM adc."+table+" t")){r.next();out.add(table+":"+r.getString(1));}}return out;}
 DurationPolicyService service(){return new DurationPolicyService(new JdbcTransactions(PgITSupport.config()),PgITSupport.authorization(PgITSupport.grants()),Clock.systemUTC());}
 JsonNode draft(DurationPolicyService s,int minutes)throws Exception {var r=s.create(UUID.randomUUID(),AuditDocuments.JSON.createObjectNode().put("projectName","SYNTHETIC-config").put("durationMinutes",minutes));assertEquals("SUCCEEDED",r.businessOutcome());return r.result().path("targetVersion");}
 JsonNode publication(JsonNode row,JsonNode old){var p=AuditDocuments.JSON.createObjectNode().put("expectedDraftToken",AuditDocuments.hash(row)).put("reason","SYNTHETIC publication");if(old==null)p.putNull("expectedCurrentRef");else p.putObject("expectedCurrentRef").put("projectId",old.path("project_id").asText()).put("versionNo",old.path("duration_version_no").intValue());return p;}
 @Test void staleTokensAndMissingExpectedCurrentRejectWithoutMutation()throws Exception {var s=service();var row=draft(s,30);long id=row.path("project_id").longValue();var bad=AuditDocuments.JSON.createObjectNode().put("projectName","SYNTHETIC edit").put("durationMinutes",50).put("expectedStateToken","stale").put("reason","SYNTHETIC");assertEquals("REJECTED",s.edit(UUID.randomUUID(),id,1,bad).businessOutcome());assertEquals(row,s.version(id,1));var p=(tools.jackson.databind.node.ObjectNode)publication(row,null);p.remove("expectedCurrentRef");assertEquals("REJECTED",s.publish(UUID.randomUUID(),id,1,p).businessOutcome());assertEquals(row,s.version(id,1));}
 @Test void twoConcurrentPublicationsHaveOnlyOneSuccessfulCurrentAndOtherRejects()throws Exception {var s=service();var first=draft(s,30);long id=first.path("project_id").longValue();var create=AuditDocuments.JSON.createObjectNode().put("projectId",Long.toString(id)).put("expectedBaseVersion",1).put("projectName","SYNTHETIC other").put("durationMinutes",45);assertEquals("SUCCEEDED",s.create(UUID.randomUUID(),create).businessOutcome());var second=s.version(id,2);try(var pool=java.util.concurrent.Executors.newVirtualThreadPerTaskExecutor()){var a=pool.submit(()->s.publish(UUID.randomUUID(),id,1,publication(first,null)));var b=pool.submit(()->s.publish(UUID.randomUUID(),id,2,publication(second,null)));var result=List.of(a.get(15,java.util.concurrent.TimeUnit.SECONDS).businessOutcome(),b.get(15,java.util.concurrent.TimeUnit.SECONDS).businessOutcome());assertEquals(1,result.stream().filter("SUCCEEDED"::equals).count());assertEquals(1,result.stream().filter("REJECTED"::equals).count());}assertEquals(1,s.current().stream().filter(n->n.path("project_id").longValue()==id).count());}
 @Test void actualLostPublishCommitReplyIsRecoveredByReferenceWithoutPayloadOrReplay()throws Exception {var s=service();var row=draft(s,30);long id=row.path("project_id").longValue();var calls=new java.util.concurrent.atomic.AtomicInteger();javax.sql.DataSource route=(javax.sql.DataSource)java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{javax.sql.DataSource.class},(p,m,a)->{if(m.getName().equals("getConnection"))return(calls.incrementAndGet()==2?PgITSupport.configProxy():PgITSupport.config()).getConnection();throw new UnsupportedOperationException();});var loss=new DurationPolicyService(new JdbcTransactions(route),PgITSupport.authorization(PgITSupport.grants()),Clock.systemUTC());var result=loss.publish(UUID.randomUUID(),id,1,publication(row,null));assertEquals("UNKNOWN",result.businessOutcome());assertEquals("SUCCEEDED",s.recover(result.requestReference()).businessOutcome());assertEquals("CURRENT",s.version(id,1).path("publication_status").asText());assertThrows(SecurityException.class,()->s.recover(result.requestReference().replaceFirst("[a-f0-9]{32}","0".repeat(32))));}
 @Test void failedSuccessAuditRollsBackPublicationAndRetainsDraft()throws Exception {var s=service();var row=draft(s,30);long id=row.path("project_id").longValue();var calls=new java.util.concurrent.atomic.AtomicInteger();javax.sql.DataSource route=(javax.sql.DataSource)java.lang.reflect.Proxy.newProxyInstance(getClass().getClassLoader(),new Class[]{javax.sql.DataSource.class},(p,m,a)->{if(m.getName().equals("getConnection")){if(calls.incrementAndGet()==2)try(var owner=PgITSupport.owner().getConnection();var st=owner.createStatement()){st.execute("REVOKE INSERT ON adc.extension_operation_audit_event FROM p0_config_app");}return PgITSupport.config().getConnection();}throw new UnsupportedOperationException();});var guarded=new DurationPolicyService(new JdbcTransactions(route),PgITSupport.authorization(PgITSupport.grants()),Clock.systemUTC());try{var r=guarded.publish(UUID.randomUUID(),id,1,publication(row,null));assertEquals("FAILED",r.businessOutcome());assertEquals(CommandRecovery.Persistence.NOT_PERSISTED,r.auditPersistence());assertEquals(row,s.version(id,1));}finally{try(var owner=PgITSupport.owner().getConnection();var st=owner.createStatement()){st.execute("GRANT INSERT ON adc.extension_operation_audit_event TO p0_config_app");}}}
 @Test void draftPublishHistoryAndIdempotencyDoNotRewriteAnyOriginalTable()throws Exception {
  var originals=originalRows();var auth=PgITSupport.authorization(PgITSupport.grants());var s=new DurationPolicyService(new JdbcTransactions(PgITSupport.config()),auth,Clock.systemUTC());var key=UUID.randomUUID();var input=AuditDocuments.parse("{\"projectName\":\"SYNTHETIC-project\",\"durationMinutes\":30}");var created=s.create(key,input);assertEquals("SUCCEEDED",created.businessOutcome());long id=created.result().path("targetVersion").path("project_id").longValue();assertEquals("SUCCEEDED",s.create(key,input).businessOutcome());var draft=s.version(id,1);var publish=AuditDocuments.JSON.createObjectNode().put("expectedDraftToken",AuditDocuments.hash(draft)).put("reason","SYNTHETIC-publish");publish.putNull("expectedCurrentRef");var p=s.publish(UUID.randomUUID(),id,1,publish);assertEquals("SUCCEEDED",p.businessOutcome());assertEquals("CURRENT",s.version(id,1).path("publication_status").asText());assertEquals("REJECTED",s.edit(UUID.randomUUID(),id,1,AuditDocuments.JSON.createObjectNode().put("projectName","bad").put("durationMinutes",40).put("expectedStateToken",AuditDocuments.hash(draft)).put("reason","bad")).businessOutcome());
  var next=AuditDocuments.JSON.createObjectNode().put("projectId",Long.toString(id)).put("expectedBaseVersion",1).put("projectName","SYNTHETIC-next").put("durationMinutes",45);assertEquals("SUCCEEDED",s.create(UUID.randomUUID(),next).businessOutcome());var old=s.version(id,1).deepCopy();var nextPublish=AuditDocuments.JSON.createObjectNode().put("expectedDraftToken",AuditDocuments.hash(s.version(id,2))).put("reason","SYNTHETIC-next-publish");nextPublish.putObject("expectedCurrentRef").put("projectId",Long.toString(id)).put("versionNo",1);assertEquals("SUCCEEDED",s.publish(UUID.randomUUID(),id,2,nextPublish).businessOutcome());var historical=s.version(id,1);assertEquals("SUPERSEDED",historical.path("publication_status").asText());for(String f:List.of("project_name","duration_minutes","published_at","published_by","publication_evidence"))assertEquals(old.get(f),historical.get(f));assertEquals(45,s.current().stream().filter(n->n.path("project_id").longValue()==id).findFirst().orElseThrow().path("duration_minutes").intValue());assertEquals(originals,originalRows());
 }
}
